cd /app && python3 -c "
import json, glob
deps={}
for pf in glob.glob('packages/*/package.json'):
    with open(pf) as f:
        pj=json.load(f)
    for section in ['dependencies','devDependencies','peerDependencies']:
        for name,ver in pj.get(section,{}).items():
            deps.setdefault(name, set()).add(ver)
# Print deps that are NOT netlify-cms internal
for name in sorted(deps):
    if name.startswith('netlify-cms'): continue
    print(name, sorted(deps[name]))
" 2>&1 | head -120

